CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA vertice_private; CREATE SCHEMA vertice_planning; CREATE SCHEMA vertice_app;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT jsonb_build_object('aal',current_setting('request.jwt.claim.aal',true))$$;
CREATE TABLE public.vertice_institutions(id uuid PRIMARY KEY,name text,tier text DEFAULT 'superior');
CREATE TABLE public.vertice_courses(id uuid PRIMARY KEY,institution_id uuid REFERENCES vertice_institutions(id),name text,code text);
CREATE TABLE public.vertice_admins(user_id uuid PRIMARY KEY);
CREATE TABLE public.vertice_memberships(user_id uuid,institution_id uuid,role text);
CREATE FUNCTION vertice_private.is_master() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT EXISTS(SELECT 1 FROM public.vertice_admins WHERE user_id=auth.uid())$$;
CREATE TABLE public.vertice_learning_staff_scope(user_id uuid,institution_id uuid,course_id uuid,active boolean);
CREATE TABLE vertice_app.strategic_plans(id uuid PRIMARY KEY,institution_id uuid,course_id uuid,version integer,status text DEFAULT 'draft',updated_at timestamptz DEFAULT now(),strategic_objectives jsonb DEFAULT '[]',operational_objectives jsonb DEFAULT '[]',risks jsonb DEFAULT '[]',alignment jsonb DEFAULT '{}',swot jsonb DEFAULT '{}');
CREATE TABLE vertice_app.semester_plannings(id uuid PRIMARY KEY,institution_id uuid,course_id uuid,version integer,status text DEFAULT 'draft',updated_at timestamptz DEFAULT now(),semester text,activities jsonb DEFAULT '[]',semester_goals jsonb DEFAULT '[]');
CREATE TABLE public.vertice_goals(id uuid PRIMARY KEY,institution_id uuid,course_id uuid,title text,indicator text,baseline numeric,baseline_date date,target numeric,unit text,direction text DEFAULT 'aumentar',source text,owner_name text,status text DEFAULT 'ativa',due_date date,updated_at timestamptz DEFAULT now());
CREATE TABLE public.vertice_goal_measurements(id uuid PRIMARY KEY,institution_id uuid,goal_id uuid,measured_on date,value numeric,source text,updated_at timestamptz DEFAULT now());
CREATE TABLE public.vertice_documents(id uuid PRIMARY KEY,institution_id uuid,course_id uuid,status text,version_number integer,approved_by uuid,approved_at timestamptz,expiry_date date,superseded_by uuid,updated_at timestamptz DEFAULT now());
CREATE TABLE public.vertice_actions(id uuid PRIMARY KEY,institution_id uuid,course_id uuid,goal_id uuid,why text,why_justification text,where_at text,where_location text,how text,how_method text,how_much text,how_much_cost numeric,what text,what_description text,who text,who_responsible text,due_date date,when_deadline date,status text,validated_by_superior uuid,evidence_doc_id uuid,evidence text,updated_at timestamptz DEFAULT now());
CREATE TABLE public.vertice_course_semester_stats(id uuid DEFAULT gen_random_uuid(),abandono integer,trancado integer,cancelado integer,transferido integer,institution_id uuid,codigo text,semestre text,matriculados integer,created_at timestamptz DEFAULT now());
CREATE TABLE public.vertice_repository_requests(id uuid PRIMARY KEY,institution_id uuid,course_id uuid,goal_id uuid,semester text,not_applicable boolean DEFAULT false,active boolean DEFAULT true);
CREATE TABLE public.vertice_repository_files(id uuid PRIMARY KEY,request_id uuid,institution_id uuid,status text,created_at timestamptz DEFAULT now(),reviewed_at timestamptz);
CREATE TABLE public.vertice_learning_course_metrics(institution_id uuid,course_id uuid,semester text,subject_code text,module text,competency text,participants integer,paired_students integer,curricular_average numeric,external_accuracy numeric,activity_rate numeric,updated_at timestamptz DEFAULT now());
CREATE TABLE public.synthetic_risk(institution_id uuid,course_id uuid,risk_level text);
CREATE VIEW public.v_student_evasion_risk AS SELECT * FROM public.synthetic_risk;
CREATE VIEW public.v_tcc_course_summary AS SELECT id course_id,institution_id,0 works_active,0 works_overdue FROM vertice_courses;
CREATE VIEW public.v_ac_course_summary AS SELECT id course_id,institution_id,0 submissions_pending FROM vertice_courses;
CREATE VIEW public.v_internship_course_summary AS SELECT id course_id,institution_id,0 placements_active FROM vertice_courses;
CREATE FUNCTION vertice_planning.school_planning(uuid,text,text,jsonb) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"strategic":{"status":"draft"},"semesters":[]}'::jsonb$$;
CREATE FUNCTION vertice_planning.school_operations_context(p_institution uuid,p_year integer) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('year',p_year,'classes',jsonb_build_array(jsonb_build_object('id','synthetic-class','enrolled',30)),'records',jsonb_build_array(jsonb_build_object('kind','finance','source','Synthetic operational register')))$$;
CREATE FUNCTION vertice_private.bi_module_snapshot(uuid) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"synthetic_institutional_sentinel":"INSTITUTION_ONLY"}'::jsonb$$;
GRANT USAGE ON SCHEMA public,auth,vertice_planning,vertice_private TO authenticated;
GRANT EXECUTE ON FUNCTION auth.uid(),auth.jwt() TO authenticated;
